window.Vibe={base:['localhost','127.0.0.1'].includes(location.hostname)?location.origin:'http://127.0.0.1:4173',token:sessionStorage.getItem('vibe-session')||'',user:null};
Vibe.api=async function(path,body){const response=await fetch(Vibe.base+'/api'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(Vibe.token?{Authorization:'Bearer '+Vibe.token}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await response.json();if(!response.ok)throw Object.assign(Error(data.error||'Request failed'),{status:response.status});return data;};
Vibe.escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
Vibe.require=async function(options={}){try{Vibe.user=await Vibe.api('/me');return Vibe.user;}catch(e){if(e.status!==401&&e.status!==403){}return new Promise((resolve,reject)=>{let register=false;const dismissible=options.dismissible??!/^\/(account|practice|studio)(?:\/|$)/.test(location.pathname);const host=document.createElement('dialog');host.className='vibe-auth';host.setAttribute('aria-label','Sign in to Vibe');host.addEventListener('cancel',event=>{event.preventDefault();if(dismissible){host.remove();reject(Error('Sign-in cancelled.'));}});document.body.append(host);host.showModal();const render=()=>{host.innerHTML=`<form class="vibe-auth-card"><a href="/">Vibe One / Vibe Law</a><h1>${register?'Create your account':'Welcome back'}</h1><p>Your projects, practice space and Codex builds.</p>${register?'<label>Name<input name="name" required autocomplete="name"></label>':''}<label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" minlength="10" maxlength="200" required autocomplete="${register?'new-password':'current-password'}"></label>${register?'<label>Start with<select name="edition"><option value="one">Vibe One</option><option value="law">Vibe Law</option></select></label>':''}<p class="vibe-auth-error" role="status"></p><button class="primary">${register?'Create account':'Sign in'}</button><button type="button" id="auth-switch">${register?'Already have an account? Sign in':'New here? Create an account'}</button><small>Local accounts on this computer. Offering access is a free local trial; billing is not connected. Codex uses the computer owner’s signed-in subscription.</small><small><a href="/downloads/">Download the local companion</a>. If the engine is offline, start Start-Platform.ps1, then <a href="http://127.0.0.1:4173/account/">open the local account</a>.</small></form>`;const editionField=host.querySelector('[name=edition]');if(editionField){let requested=new URLSearchParams(location.search).get('edition');try{requested||=localStorage.getItem('vibe-edition');}catch{}if(['one','law'].includes(requested))editionField.value=requested;}host.querySelector('#auth-switch').onclick=()=>{register=!register;render();};host.querySelector('form').onsubmit=async event=>{event.preventDefault();const submit=host.querySelector('.primary');submit.disabled=true;try{const data=await Vibe.api('/auth/'+(register?'register':'login'),Object.fromEntries(new FormData(event.target)));Vibe.token=data.token;Vibe.user=data.user;sessionStorage.setItem('vibe-session',data.token);host.remove();resolve(data.user);}catch(error){host.querySelector('[role="status"]').textContent=error.message.includes('fetch')?'Local engine unavailable. Start Start-Platform.ps1 and open the local account.':error.message;submit.disabled=false;}};};render();host.querySelector('input')?.focus();});}};
Vibe.logout=async()=>{await Vibe.api('/auth/logout',{});sessionStorage.removeItem('vibe-session');sessionStorage.removeItem('wb-pair-token');location.href='/account/';};
